def validate_policy(policy, kind="checkpoint"):
    if not isinstance(policy, dict):
        return ['policy must be an object']
    if kind not in ALLOWED_KEYS:
        return ["unknown policy kind"]
    errors = []
    if set(policy) != set(ALLOWED_KEYS[kind]):
        errors.append("policy key set mismatch: " + kind)
    for key, value in EXPECTED.items():
        actual = policy.get(key)
        if type(actual) is not type(value) or actual != value:
            errors.append('invalid policy field: ' + key)
    for key in REMOVED:
        if key in policy:
            errors.append('obsolete turn cap: ' + key)
    return errors
